  (* [comment removed for export] *)
  Lemma sh_lo_img : forall A, AIMG_TOP <= A -> 0x800c8800 <= sh A.
  Proof. intros A H. unfold sh, AIMG_TOP in *. rewrite ASHADOW_BASE_val. Z.div_mod_to_equations. lia. Qed.

  Lemma aapp_lo_img : forall A n, aapp A n -> AIMG_TOP <= A.
  Proof. intros A n H. exact (aapp_above_image A n H). Qed.

  Lemma aapp_hi_aceil : forall A n, aapp A n -> A + n <= aceil.
  Proof. intros A n H. exact (aapp_below_aceil A n H). Qed.

  (* [comment removed for export] *)
  Lemma fresh_frame_aapp : forall (H : asr) LF k ff fp, fresh_frame H LF k ff fp ->
    aapp ff (fsz k) /\ aapp fp 1 /\ aapp (ff - AFS_HDR) (AFS_HDR + fsz k).
  Proof.
    intros H LF k ff fp FF.
    pose proof (fresh_frame_facts H LF k ff fp FF) as (K0 & K1 & K2 & K3 & K4 & K5 & K6 & K7 & K8 & K9 & K10 & K11 & K12 & K13).
    pose proof (fsz_pos k ltac:(lia)) as FP. unfold AFS_HDR, AFS_FLAGS, AFS_SIZE in *.
    split; [| split]; (eapply aapp_sub; [exact K13| lia| lia]).
  Qed.
End K.

(* [comment removed for export] *)
Definition aapp_seen (A n : Z) : Prop := True.
Definition placed (A n : Z) (P : Prop) : Prop := P.
Lemma placedI : forall A n (P : Prop), P -> placed A n P. Proof. intros A n P p. exact p. Qed.

(* [comment removed for export] *)
Ltac fold_nsh_lits K :=
  repeat match type of K with
  | context [(?a + 7) / 8] => let v := eval cbv in ((a + 7) / 8) in is_Zlit v; change ((a + 7) / 8) with v in K
  end.

Ltac aapp_fact H :=
  lazymatch type of H with
  | aapp ?A0 ?n0 =>
    let A1 := eval cbn [blk_addr blk_size fst snd] in A0 in
    let A := eval unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in A1 in
    let n1 := eval cbn [blk_addr blk_size fst snd] in n0 in
    let n := eval unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in n1 in
    lazymatch goal with
    | _ : aapp_seen A n |- _ => idtac
    | _ =>
      let K := fresh "APP" in let K2 := fresh "APQ" in let M := fresh "APPs" in
      pose proof (aapp_num2 _ _ H ltac:(cbn [blk_addr blk_size fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *;
                                     rewrite ?fsz_1, ?fsz_4;
                                     first [lia | cbn; lia
                                           | apply (Z.le_trans 0 64); [lia| apply fsz_pos; lia]
                                           | unfold fsz, fshn in *;
                                             repeat match goal with |- context [2 ^ ?k] =>
                                               lazymatch goal with _ : 0 <= 2 ^ k |- _ => fail | _ => pose proof (Z.pow_nonneg 2 k ltac:(lia)) end end;
                                             lia
                                           | cbv; first [discriminate | congruence]])) as K;
      cbn [blk_addr blk_size fst snd] in K; unfold nsh, AFS_SIZE, AFS_HDR, AFS_FLAGS in K;
      rewrite ?fsz_1, ?fsz_4 in K; fold_nsh_lits K;
      destruct K as [K K2];
      lazymatch type of K with ?P => change P with (placed A n P) in K end;
      pose proof (I : aapp_seen A n) as M
    end
  end.

(* [comment removed for export] *)
Definition aapp_dug (P : Prop) : Prop := True.
Ltac aapp_keep H := lazymatch type of H with aapp _ _ => idtac | _ => clear H end.
Ltac aapp_dig K :=
  let T := fresh "DG" in
  pose proof K as T;
  repeat (lazymatch type of T with
          | _ /\ _ => let a := fresh "DGa" in destruct T as [a T]; aapp_keep a
          end);
  aapp_keep T.

(* [comment removed for export] *)
Ltac aapp_facts :=
  repeat match goal with
  | K : ?X /\ ?Y |- _ =>
      lazymatch goal with
      | _ : aapp_dug (X /\ Y) |- _ => fail
      | _ => lazymatch type of K with
             | context [aapp _ _] => aapp_dig K; let M := fresh "DUG" in pose proof (I : aapp_dug (X /\ Y)) as M
             end
      end
  end;
  repeat match goal with
  | K : aapp ?A ?n |- _ => progress (aapp_fact K)
  end.

(* [comment removed for export] *)
Ltac n8b :=
  try acb; try aapp_facts; unfold AIMG_TOP, ALOWSH_LO, AHI_LO, AAPP_HI, AFS_SIZE, AFS_HDR, AFS_FLAGS in *.

(* [comment removed for export] *)
Ltac side_split :=
  repeat match goal with
  | K : placed ?A _ _ |- ?G =>
      lazymatch G with context [A] =>
        unfold placed in K;
        first [ destruct K as [(? & ? & ? & ?)|(? & ?)] | destruct K as [K|K] ]
      end
  end.
Ltac side_split_all :=
  repeat match goal with
  | K : placed _ _ _ |- _ => unfold placed in K; first [ destruct K as [(? & ? & ? & ?)|(? & ?)] | destruct K as [K|K] ]
  end.
Ltac lia_t1 := zify_prune; zify_noeuclid; Z.euclidean_division_equations_cleanup; xlia zchecker.
Ltac lia_t2 := zify_prune; Zify.zify; xlia zchecker.
Ltac lia_t3 := Zify.zify; xlia zchecker.

(* [comment removed for export] *)
Ltac lia_arith :=
  first [ lia_t1
        | progress side_split; lia_t1
        | lia_t2 ].

(* [comment removed for export] *)
Ltac aconst_via_aapp :=
  match goal with
  | K : aapp ?A ?n |- _ => solve [apply (aconst_ok_aapp A n _ _ K); cbn [fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : aapp ?A ?n /\ _ |- _ => solve [apply (aconst_ok_aapp A n _ _ (proj1 K)); cbn [fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : _ /\ aapp ?A ?n |- _ => solve [apply (aconst_ok_aapp A n _ _ (proj2 K)); cbn [fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  end.
Ltac stack0_via_aapp :=
  match goal with
  | K : aapp ?A ?n |- _ => solve [apply (stack0_ok_aapp A n _ _ K); cbn [fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : aapp ?A ?n /\ _ |- _ => solve [apply (stack0_ok_aapp A n _ _ (proj1 K)); cbn [fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : _ /\ aapp ?A ?n |- _ => solve [apply (stack0_ok_aapp A n _ _ (proj2 K)); cbn [fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  end.
(* [comment removed for export] *)
Ltac hiwin_via_aapp :=
  match goal with
  | K : aapp ?A ?n |- _ => solve [pose proof (aapp_not_shadowland A n K); pose proof (aapp_above_image A n K); cbn [fst snd] in *; unfold AIMG_TOP, ALOWSH_LO, AHI_LO, AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : aapp ?A ?n /\ _ |- _ => solve [pose proof (aapp_not_shadowland A n (proj1 K)); pose proof (aapp_above_image A n (proj1 K)); cbn [fst snd] in *; unfold AIMG_TOP, ALOWSH_LO, AHI_LO, AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : _ /\ aapp ?A ?n |- _ => solve [pose proof (aapp_not_shadowland A n (proj2 K)); pose proof (aapp_above_image A n (proj2 K)); cbn [fst snd] in *; unfold AIMG_TOP, ALOWSH_LO, AHI_LO, AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  end.
Ltac aconst_win := first [aconst_via_aapp | apply aconst_ok_hi].
Ltac aconst_winH := first [aconst_via_aapp | apply aconst_ok_high].
Ltac stack0_win := first [stack0_via_aapp | apply stack0_ok_app].

(* [comment removed for export] *)
Ltac wins_hi_tac :=
  unfold wins_hi; repeat (apply Forall_cons; [cbn; acb; unfold aapp, aapp_lo, aapp_hi, AIMG_TOP, ALOWSH_LO, AHI_LO in *; lia|]); apply Forall_nil.

(* [comment removed for export] *)
Ltac inapp_win :=
  first [ solve [right; n8b; unfold AFS_SIZE, AFS_HDR in *; lia]
        | solve [left; unfold ASHADOW_BASE in *; n8b; unfold AFS_SIZE, AFS_HDR in *; lia]
        | solve [unfold in_app_mem, ASHADOW_BASE in *; n8b; lia] ].

(* [comment removed for export] *)
Ltac aapp_win :=
  first [ assumption
        | match goal with
          | K : aapp ?A ?n |- _ => solve [apply (aapp_sub A n _ _ K); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          | K : aapp ?A ?n /\ _ |- _ => solve [apply (aapp_sub A n _ _ (proj1 K)); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          | K : _ /\ aapp ?A ?n |- _ => solve [apply (aapp_sub A n _ _ (proj2 K)); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          | K : ablock_range _ ?A ?n |- _ =>
              solve [apply (aapp_sub A n _ _ (proj2 (proj2 (proj2 (proj2 (proj2 (proj2 K))))))); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          end ].

Ltac lia ::=
  unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *;
  first [ lazymatch goal with
          | |- aapp _ _ => aapp_win
          | |- _ /\ _ => split; lia
          end
        | lia_t1
        | progress side_split; lia_t1
        | lia_t2
        | lia_t3
        | progress side_split; first [lia_t2 | lia_t3]
        | progress side_split_all; lia_t1 ].
